            line("L-2", "A", "S1", "2026-04-10", 10000),  # 1000
            line("L-4", "B", "S1", "2026-04-01", 30000),  # 3000 uncapped -> 2400 (own cap)
        ]
        # Credit: A = 1000 + 1000 + 400 = 2400; B = 2400. Charges = 70000.
